using System;
using System.Web;
using System.Web.UI.HtmlControls;
using Sunplus.Accounting.Core.Common;
using Sunplus.Accounting.Presentation;
using Sunplus.Accounting.WcfServiceLibrary.CreditTerm;

/// <summary>
/// CITS
/// </summary>
public partial class CreditTerm_Creditterm_Group_Feed : PageBase
{
    public string strContent = string.Empty;
    public string strfilter = string.Empty;
    public int selectedGroupId = 0;

    protected void Page_Load(object sender, EventArgs e)
    {

        HtmlLink hl = new HtmlLink();

        hl.Href = "../Scripts/_Libs/FanexGrid/Fanex.Grid.css?v=" + AccCommon.Version();
        hl.Attributes.Add("type", "text/css");
        hl.Attributes.Add("rel", "stylesheet");

        int.TryParse(Request["groupid"], out selectedGroupId);

        if (Request["IsExport"] == "1") // export excel
		{
            if (selectedGroupId > 0)
			{
                ICreditTermService creditTermService = new CreditTermService();
                creditTermService.ExportExcelMemberByGroupId(selectedGroupId);
			}
		}
		else
		{
            string groupMaxLoss = "N/A";
            
            strContent = CreditTermHTML.GetContentCreditTerm(HttpContext.Current, ref groupMaxLoss);
            strfilter = CreditTermHTML.GetContentCreditTermFilter(HttpContext.Current, groupMaxLoss);
        }
    }
}
